	 *
	 *   // Part 1
	 *   for i in 0..N-1
	 *     for j in 0..N-1
	 *       x1[i] += A[i][j] * y_1[j];
	 *
	 *   // Part 2
	 *   for i in 0..N-1
	 *     for j in 0..N-1
