	// 2D layout for matrix A: dimensions 'i' (rows) and 'j' (columns)
	DEFINE_PROTO_STRUCT(a_layout, j_vec ^ i_vec);
} tuning;

// initialization function
void init_array(auto x1, auto x2, auto y_1, auto y_2, auto A) {
	// x1, x2, y_1, y_2: 1D over 'i'
	// A: 2D over 'i' x 'j'
	using namespace noarr;

	auto n = x1 | get_length<'i'>();

	// Initialize the four vectors
	traverser(x1, x2, y_1, y_2).for_each([=](auto state) {
		auto i = get_index<'i'>(state);

		x1[state] = (num_t)((i % n)) / n;
		x2[state] = (num_t)(((i + 1) % n)) / n;
		y_1[state] = (num_t)(((i + 3) % n)) / n;
		y_2[state] = (num_t)(((i + 4) % n)) / n;
	});

	// Initialize matrix A: A[i][j] = (i * j % n) / n
	auto nA = A | get_length<'i'>();

	traverser(A).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);
		A[state] = (num_t)((i * j) % nA) / nA;
	});
}

// computation kernel
//
// Original mathematical specification:
//
//   x1[i] = x1[i] + sum_j A[i][j] * y_1[j]
//   x2[i] = x2[i] + sum_j A[j][i] * y_2[j]
//
// The original implementation performed these as two separate passes
// over A (and used a transposed view A_t for the second pass).
//
// The optimized kernel below fuses the two passes into a single
// traversal of A:
//
//   For each (i, j):
//     x1[i] += A[i][j] * y_1[j]
//     x2[j] += A[i][j] * y_2[i]
//
// Note that:
//   x2[j] = x2[j] + sum_i A[i][j] * y_2[i]
//         = x2[j] + sum_i A[i][j] * y_2[i]   (i is just a dummy index)
//         = x2[j] + sum_k A[k][j] * y_2[k]
//
// which is exactly the same vector A^T * y_2, only indexed by 'j'
// instead of 'i'. Since x2 is just a 1D vector, renaming its index
// dimension from 'i' to 'j' does not change the stored values.
// We therefore compute x2 in a renamed view x2_j over 'j', and the
// original x2 bag sees the same resulting numbers.
//
[[gnu::flatten, gnu::noinline]]
void kernel_mvt(auto x1, auto x2, auto y_1, auto y_2, auto A) {
	// x1, x2, y_1, y_2: 1D over 'i'
	// A: 2D over 'i' x 'j'
	using namespace noarr;

	// View y_1 as a vector over 'j' so that y_1_j[state] uses the 'j' index.
	auto y_1_j = y_1.get_ref() ^ noarr::rename<'i', 'j'>();

	// View x2 as a vector over 'j'; we accumulate into this view.
	auto x2_j  = x2.get_ref()  ^ noarr::rename<'i', 'j'>();

#pragma scop
	// Fused kernel:
	//
	// for (i = 0; i < N; i++) {
	//   num_t acc_x1 = x1[i];
	//   num_t y2_i   = y_2[i];
	//   for (j = 0; j < N; j++) {
	//     num_t a_ij = A[i][j];
	//     acc_x1   += a_ij * y_1[j];
	//     x2[j]    += a_ij * y_2_i;
	//   }
	//   x1[i] = acc_x1;
	// }
	//
	// Benefits:
	// - A is streamed once instead of twice.
	// - x1[i] is loaded and stored once per row, with accumulation kept
	//   in a register, improving cache usage and enabling better
	//   vectorization of the inner loop.

	noarr::traverser(A, x1, x2_j, y_1_j, y_2)
	    .template for_dims<'i'>([&](auto trav_i) {
		    // trav_i has the current index in 'i' fixed; its state can be
		    // used to index 1D structures over 'i'.
		    const auto state_i = trav_i.state();

		    // Load x1[i] and y_2[i] once per row into registers.
		    num_t       x1_i = x1[state_i];
		    const num_t y2_i = y_2[state_i];

		    // Iterate over all columns 'j' for this fixed row 'i'.
		    trav_i.for_each([&](auto state_ij) {
			    // state_ij carries both 'i' and 'j'.
			    const num_t a_ij  = A[state_ij];
			    const num_t y1_jv = y_1_j[state_ij];

			    // Part 1: x1[i] += A[i][j] * y_1[j]
			    x1_i += a_ij * y1_jv;

			    // Part 2 (rewritten): x2[j] += A[i][j] * y_2[i]
			    // This is mathematically equivalent to the original
			    // x2[i] += A[j][i] * y_2[j], just with indices renamed.
			    x2_j[state_ij] += a_ij * y2_i;
		    });

		    // Store the updated x1[i] back to memory.
		    x1[state_i] = x1_i;
	    });
#pragma endscop
}

